mapper.select:
SELECT m.major_id AS id, m.major_name AS majorName, m.major_code AS majorCode, m.college_id AS collegeId, c.college_name AS collegeName, m.major_status AS majorStatus, m.major_remark AS majorRemark, m.gmt_create AS gmtCreate, m.gmt_modified AS gmtModified FROM edu_major m LEFT JOIN edu_college c ON m.college_id = c.college_id AND c.college_deleted = 0 WHERE m.major_deleted = 0
AND m.major_name LIKE CONCAT('%', #{majorName}, '%')
AND m.major_code LIKE CONCAT('%', #{majorCode}, '%')
AND m.college_id = #{collegeId}
AND m.major_status = #{majorStatus}
ORDER BY m.major_code
